import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../domain/useCase/update_password_use_case.dart';import '../Cubit/user_cubit.dart';import '../../../../../../main.dart';import '../../../../../../Config/Routes/route_name.dart';import '../../../../../../Core/Resources/app_colors.dart';import '../../../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../../../Core/Utils/Extensions/widget_extension.dart';import '../../../../../../Core/Utils/Widget/TextField/build_text_field.dart';import '../../../../../Global/Authentication/presentation/components/build_social_login_button.dart';import '../../../../../../Core/Utils/Widget/Images/build_image.dart';import '../../../../App/Home/presentation/manager/home_cubit.dart';import '../../data/models/update_user.dart';import '../../domain/repositories/user_repo_imp.dart';import '../../domain/useCase/update_user_use_case.dart';class UserEditeScreen extends StatefulWidget {  const UserEditeScreen({super.key});  @override  State<UserEditeScreen> createState() => _UserEditeScreenState();}final formKey = GlobalKey<FormState>();final TextEditingController nameController = TextEditingController();final TextEditingController emailController = TextEditingController();final TextEditingController phoneController = TextEditingController();final TextEditingController addressController = TextEditingController();class _UserEditeScreenState extends State<UserEditeScreen> {  @override  void initState() {    final user = context.read<HomeCubit>().state.userDataModel;    nameController.text = user?.name ?? "";    emailController.text = user?.email ?? "";    phoneController.text = user?.phone ?? "";    super.initState();  }  @override  Widget build(BuildContext context) {    final local = context.local;    return BlocProvider(        create: (context) => UserCubit(            UpdateUserUseCase(              userRepoImp: UserRepoImp(),            ),            UpdatePasswordUseCase(              userRepoImp: UserRepoImp(),            )),        child: BlocBuilder<UserCubit, UserClassState>(          builder: (context, state) {            return [              SliverList.list(children: [                Form(                  key: formKey,                  child: Column(children: [                    CircleAvatar(                      backgroundColor: Colors.transparent,                      radius: 75.r,                      child: BuildImageAssets(                        url: context                            .read<HomeCubit>()                            .state                            .userDataModel!                            .photoUrl                            .toString(),                        setDefaultImage: true,                      ),                    ),                    DefaultTextFormField(                      text: local.name,                      type: TextInputType.name,                      isTextOut: false,                      isTextIn: false,                      controller: nameController,                    ),                    DefaultTextFormField(                      text: local.email,                      type: TextInputType.name,                      isTextOut: false,                      isTextIn: false,                      controller: emailController,                    ),                    DefaultTextFormField(                      text: local.phone,                      type: TextInputType.name,                      isTextOut: false,                      isTextIn: false,                      controller: phoneController,                    ),                    BuildSocialLoginButton(                      loading: state.loading,                      isSpace: false,                      text: local.Save,                      backgroundColor: AppColors.primaryColor,                      onPressed: () {                        if (formKey.currentState!.validate()) {                          final UpdateUser updateUser = UpdateUser(                            nameController.text,                            emailController.text,                            phoneController.text,                            context                                .read<HomeCubit>()                                .state                                .userDataModel!                                .photoUrl                                .toString(),                          );                          context                              .read<UserCubit>()                              .updateUser(context, updateUser);                        }                      },                    ),                    20.verticalSpace,                    BuildSocialLoginButton(                        isSpace: false,                        text: local.AddAddress,                        backgroundColor: AppColors.grayscale70,                        onPressed: () {                          kNavigationService                              .navigateTo(AppRoutes.addAddressScreen);                        }),                    10.verticalSpace,                    BuildSocialLoginButton(                      isSpace: false,                      text: local.ChangePassword,                      backgroundColor: AppColors.grayscale70,                      onPressed: () {                        kNavigationService                            .navigateTo(AppRoutes.changePasswordScreen);                      },                    )                  ]),                )              ])            ].styledAppPages(              withAll: true,              appbar: true,              widgetAppbar: AppBar(                title: Text(local.Profile),                centerTitle: true,              ),            );          },        ));  }}